def keyword_search(term):
    # keyword search for an exact product code
    catalog = {"FX-100": "Product FX-100 is our flagship router."}
    return catalog.get(term)

def semantic_search(query):
    # semantic search for a general description
    return "The flagship router supports gigabit speeds."

def build_retrieval_plan(query):
    # estimate the searches this query needs, before running any of them
    return [
        {"strategy": "keyword", "input": "FX-100"},
        {"strategy": "semantic", "input": "flagship router speed"},
    ]

def execute_retrieval_plan(plan):
    results = []
    for step in plan:
        if step["strategy"] == "keyword":
            result = keyword_search(step["input"])
        else:
            result = semantic_search(step["input"])
        if result is None:
            # revise the plan when a search comes up empty
            results.append("Step skipped, no result found, plan revised.")
            continue
        results.append(result)
    return results

query = "Tell me about the FX-100 flagship router's speed"
plan = build_retrieval_plan(query)
results = execute_retrieval_plan(plan)

print("Retrieval plan:")
for step in plan:
    print(f"  {step}")
print("\nResults:")
for r in results:
    print(f"  {r}")
